test("Cupid prepares internal component callee and bind before refusal, while getter errors retain the same Error", async () => {
  for (const point of ["callee", "bind", "throw"] as const) {
    const f = fixture("cupid"), original = f.world.addComponent,
      error = new Error("original_lovers_component_getter_failure"), trace: string[] = [];
    const install = function (this: World, ...args: Parameters<World["addComponent"]>) {
      trace.push("write");
      return original.apply(this, args);
    };
    if (point === "bind") Object.defineProperty(install, "bind", { get() {
      trace.push("bind");
      retireRoleExecution(f.role);
      return Function.prototype.bind;
    } });
    Object.defineProperty(f.world, "addComponent", { get() {
      trace.push("callee");
      if (point !== "bind") retireRoleExecution(f.role);
      if (point === "throw") throw error;
      return install;
    } });
    if (point === "throw") await expect(run(f)).rejects.toBe(error);
    else await run(f);
    expect(trace).toEqual(point === "bind" ? ["callee", "bind"] : ["callee"]);
    unpaid(f);
  }
});

